import { useState, useEffect } from 'react';

function StarDisplay({ avg, count }) {
  const full  = Math.floor(avg);
  const half  = avg - full >= 0.5;
  return (
    <div className="star-display">
      {[1, 2, 3, 4, 5].map((s) => (
        <span key={s} className={`star-disp ${s <= full ? 'star-full' : (s === full + 1 && half ? 'star-half' : 'star-empty')}`}>
          ★
        </span>
      ))}
      <span className="star-avg">{avg > 0 ? avg.toFixed(1) : '—'}</span>
      <span className="star-count">({count} değerlendirme)</span>
    </div>
  );
}

function Profile({ user }) {
  const [ratings, setRatings] = useState([]);
  const [reservations, setReservations] = useState([]);
  const [vehicles, setVehicles] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      const promises = [
        fetch(`http://localhost:3003/api/ratings/user/${user.id}`).then(r => r.json()),
        fetch('http://localhost:3003/api/reservations').then(r => r.json()),
      ];
      if (user.role === 'owner') {
        promises.push(fetch('http://localhost:3002/api/vehicles').then(r => r.json()));
      }
      const results = await Promise.all(promises);
      setRatings(results[0]);
      setReservations(results[1]);
      if (user.role === 'owner') setVehicles(results[2].filter(v => v.ownerId === user.id));
      setLoading(false);
    };
    load();
  }, [user.id, user.role]);

  const avgRating = ratings.length > 0
    ? ratings.reduce((s, r) => s + r.stars, 0) / ratings.length
    : 0;

  const myRentals = reservations.filter(r => r.userId === user.id && r.status === 'confirmed');
  const myEarnings = reservations
    .filter(r => vehicles.some(v => v.id === r.vehicleId) && r.status === 'confirmed')
    .reduce((s, r) => s + r.amount, 0);

  const roleLabel = user.role === 'owner' ? 'Araç Sahibi' : 'Kiracı';
  const roleIcon  = user.role === 'owner' ? '🏠' : '🚗';

  if (loading) return <div className="loading">Yükleniyor...</div>;

  return (
    <div className="profile-page">
      <div className="profile-card">
        <div className="profile-avatar">{user.name.charAt(0).toUpperCase()}</div>
        <h2 className="profile-name">{user.name}</h2>
        <span className="profile-role-badge">{roleIcon} {roleLabel}</span>
        <p className="profile-university">🎓 {user.university}</p>

        <StarDisplay avg={avgRating} count={ratings.length} />
      </div>

      <div className="profile-stats">
        {user.role === 'renter' && (
          <>
            <div className="profile-stat">
              <span className="profile-stat-val">{myRentals.length}</span>
              <span className="profile-stat-label">Tamamlanan Kiralama</span>
            </div>
            <div className="profile-stat">
              <span className="profile-stat-val">{reservations.filter(r => r.userId === user.id).length}</span>
              <span className="profile-stat-label">Toplam Talep</span>
            </div>
          </>
        )}
        {user.role === 'owner' && (
          <>
            <div className="profile-stat">
              <span className="profile-stat-val">{vehicles.length}</span>
              <span className="profile-stat-label">Toplam İlan</span>
            </div>
            <div className="profile-stat">
              <span className="profile-stat-val">₺{myEarnings.toLocaleString()}</span>
              <span className="profile-stat-label">Toplam Kazanç</span>
            </div>
          </>
        )}
        <div className="profile-stat">
          <span className="profile-stat-val">{ratings.length}</span>
          <span className="profile-stat-label">Değerlendirme</span>
        </div>
        <div className="profile-stat">
          <span className="profile-stat-val">{avgRating > 0 ? avgRating.toFixed(1) : '—'}</span>
          <span className="profile-stat-label">Ortalama Puan</span>
        </div>
      </div>

      {ratings.length > 0 && (
        <div className="profile-reviews">
          <h3>Değerlendirmeler</h3>
          <div className="reviews-list">
            {ratings.slice().reverse().map((r) => (
              <div key={r.id} className="review-item">
                <div className="review-header">
                  <div className="review-stars">
                    {[1,2,3,4,5].map(s => (
                      <span key={s} className={s <= r.stars ? 'star-full' : 'star-empty'}>★</span>
                    ))}
                  </div>
                  <span className="review-from">{r.fromName}</span>
                </div>
                {r.comment && <p className="review-comment">"{r.comment}"</p>}
                <span className="review-date">{new Date(r.createdAt).toLocaleDateString('tr-TR')}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default Profile;
